# RANGE frames with an offset (R50): RANGE BETWEEN n PRECEDING AND m FOLLOWING reaches the rows whose ORDER BY value is within n / m of the current row's (numbers with places, INTERVAL for a date),
# ASC and DESC, NULL keys (their own peer group), frames that hold no row (also ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING), and the errors for an unfit ORDER BY.
--CREATE TABLE rf (id INT PRIMARY KEY, v INT, d DECIMAL(6,2), dt DATE, ts DATETIME, s VARCHAR(5))
--INSERT INTO rf VALUES (1,10,1.5,'2024-01-01','2024-01-01 00:00:00','a'),(2,15,2.5,'2024-01-03','2024-01-01 00:30:00','b'),(3,30,3.5,'2024-01-08','2024-01-01 02:00:00','c'),(4,NULL,NULL,NULL,NULL,'d'),(5,15,4.0,'2024-02-01','2024-01-02 00:00:00','e'),(6,NULL,5.0,'2024-03-01','2024-01-03 00:00:00',NULL)
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE BETWEEN 10 PRECEDING AND CURRENT ROW) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) s FROM rf ORDER BY id
SELECT id, v, COUNT(*) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) c FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v DESC RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v DESC RANGE BETWEEN 10 PRECEDING AND CURRENT ROW) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE BETWEEN UNBOUNDED PRECEDING AND 5 FOLLOWING) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND UNBOUNDED FOLLOWING) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE BETWEEN 20 PRECEDING AND 10 PRECEDING) s FROM rf ORDER BY id
SELECT id, v, COUNT(*) OVER (ORDER BY v RANGE BETWEEN 20 PRECEDING AND 10 PRECEDING) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE BETWEEN 1 FOLLOWING AND 10 FOLLOWING) s FROM rf ORDER BY id
SELECT id, v, SUM(v) OVER (ORDER BY v RANGE 5 PRECEDING) s FROM rf ORDER BY id
SELECT id, d, SUM(d) OVER (ORDER BY d RANGE BETWEEN 1.5 PRECEDING AND CURRENT ROW) s FROM rf ORDER BY id
SELECT id, d, SUM(d) OVER (ORDER BY d RANGE BETWEEN 1 PRECEDING AND 1 FOLLOWING) s FROM rf ORDER BY id
SELECT id, dt, COUNT(*) OVER (ORDER BY dt RANGE BETWEEN INTERVAL 7 DAY PRECEDING AND CURRENT ROW) c FROM rf ORDER BY id
SELECT id, dt, COUNT(*) OVER (ORDER BY dt RANGE BETWEEN INTERVAL 1 MONTH PRECEDING AND CURRENT ROW) c FROM rf ORDER BY id
SELECT id, dt, COUNT(*) OVER (ORDER BY dt RANGE BETWEEN INTERVAL 2 DAY PRECEDING AND INTERVAL 5 DAY FOLLOWING) c FROM rf ORDER BY id
SELECT id, ts, COUNT(*) OVER (ORDER BY ts RANGE BETWEEN INTERVAL 1 HOUR PRECEDING AND CURRENT ROW) c FROM rf ORDER BY id
SELECT id, ts, COUNT(*) OVER (ORDER BY ts RANGE BETWEEN INTERVAL 30 MINUTE PRECEDING AND INTERVAL 30 MINUTE FOLLOWING) c FROM rf ORDER BY id
SELECT id, dt, COUNT(*) OVER (ORDER BY dt DESC RANGE BETWEEN INTERVAL 7 DAY PRECEDING AND CURRENT ROW) c FROM rf ORDER BY id
SELECT id, SUM(v) OVER (ORDER BY v, id RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) FROM rf
SELECT id, SUM(v) OVER (RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) FROM rf
SELECT id, SUM(v) OVER (ORDER BY s RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) FROM rf
SELECT id, SUM(v) OVER (ORDER BY v RANGE BETWEEN INTERVAL 1 DAY PRECEDING AND CURRENT ROW) FROM rf
SELECT id, SUM(v) OVER (ORDER BY dt RANGE BETWEEN 1 PRECEDING AND CURRENT ROW) FROM rf
SELECT id, SUM(v) OVER (ORDER BY v RANGE BETWEEN CURRENT ROW AND 5 PRECEDING) FROM rf
SELECT id, SUM(v) OVER (ORDER BY v RANGE BETWEEN 5 FOLLOWING AND 1 FOLLOWING) FROM rf ORDER BY id
SELECT id, FIRST_VALUE(id) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) f, LAST_VALUE(id) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND 5 FOLLOWING) l FROM rf ORDER BY id
SELECT id, MIN(id) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) mn, MAX(id) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) mx, AVG(v) OVER (ORDER BY v RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) av FROM rf ORDER BY id
SELECT id, SUM(v) OVER (PARTITION BY id > 3 ORDER BY v RANGE BETWEEN 5 PRECEDING AND CURRENT ROW) FROM rf ORDER BY id
SELECT id, SUM(v) OVER (ORDER BY v ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) s FROM rf ORDER BY id
SELECT id, COUNT(*) OVER (ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) s FROM rf ORDER BY id
SELECT id, SUM(v) OVER (ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) s FROM rf ORDER BY id
SELECT id, FIRST_VALUE(v) OVER (ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING) f, LAST_VALUE(v) OVER (ORDER BY id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) l FROM rf ORDER BY id
SELECT id, SUM(v) OVER (ORDER BY id ROWS BETWEEN 1.5 PRECEDING AND CURRENT ROW) FROM rf
SELECT SUM(v) OVER (ORDER BY id ROWS BETWEEN UNBOUNDED FOLLOWING AND CURRENT ROW) FROM rf
SELECT SUM(v) OVER (ORDER BY id ROWS BETWEEN CURRENT ROW AND UNBOUNDED PRECEDING) FROM rf
SELECT SUM(v) OVER (ORDER BY id ROWS BETWEEN 1 FOLLOWING AND CURRENT ROW) FROM rf
SELECT SUM(v) OVER (ORDER BY id ROWS BETWEEN 1 FOLLOWING AND 1 PRECEDING) FROM rf
SELECT SUM(v) OVER (ORDER BY id ROWS BETWEEN CURRENT ROW AND 1 PRECEDING) FROM rf
SELECT SUM(v) OVER (ORDER BY id ROWS BETWEEN 1 FOLLOWING AND UNBOUNDED PRECEDING) FROM rf
SELECT SUM(v) OVER (ORDER BY id RANGE BETWEEN UNBOUNDED FOLLOWING AND CURRENT ROW) FROM rf
SELECT SUM(v) OVER (ORDER BY id RANGE BETWEEN CURRENT ROW AND 1 PRECEDING) FROM rf
SELECT id, SUM(v) OVER (ORDER BY id ROWS BETWEEN 2 FOLLOWING AND 1 FOLLOWING) FROM rf ORDER BY id
SELECT id, SUM(v) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND 2 PRECEDING) FROM rf ORDER BY id
